  "ui/dialog.set": { req: { "dialog": "settings" | "export" | "shortcuts" | "recreatePlugins"; "open": boolean; "tab"?: "audio" | "midi" | "plugins" | "general" | "llm"; }; reply: { "open": boolean; } };
